7	func TestEnvSkillsRoundtrip(t *testing.T) {
8		t.Parallel()
9		skills := []string{"/pr-review-toolkit:review-pr", "/test-auditor"}
10		encoded, err := EncodeSkills(skills)
11		if err != nil {
12			t.Fatalf("encode: %v", err)
13		}
14		decoded, err := DecodeSkills(encoded)
15		if err != nil {
16			t.Fatalf("decode: %v", err)
17		}
18		if len(decoded) != len(skills) {
19			t.Fatalf("got %d skills, want %d", len(decoded), len(skills))
20		}
21		for i := range skills {
22			if decoded[i] != skills[i] {
23				t.Errorf("skill[%d]: got %q, want %q", i, decoded[i], skills[i])
24			}
25		}
26	}
