24	func TestEventSwitch(t *testing.T) {
25		t.Parallel()
26		cases := []struct {
27			name string
28			ev   Event
29			want string
30		}{
31			{"Started", Started{}, "started"},
32			{"AssistantText", AssistantText{Text: "narrative"}, "text"},
33			{"ToolCall", ToolCall{Name: "read"}, "tool"},
34			{"Tokens", Tokens{In: 1, Out: 2}, "tokens"},
35			{"Finished", Finished{Success: true}, "finished"},
36			{"RunError", RunError{Err: errors.New("x")}, "error"},
37		}
38		for _, tc := range cases {
39			t.Run(tc.name, func(t *testing.T) {
40				t.Parallel()
41				var got string
42				switch tc.ev.(type) {
43				case Started:
44					got = "started"
45				case AssistantText:
46					got = "text"
47				case ToolCall:
48					got = "tool"
49				case Tokens:
50					got = "tokens"
51				case Finished:
52					got = "finished"
53				case RunError:
54					got = "error"
