1	// lifecycle.go implements the generic lifecycle event dispatcher.
2	// It routes normalized events from any agent to the appropriate framework actions.
3	//
4	// The dispatcher inverts the current flow from "agent handler calls framework functions"
5	// to "framework dispatcher calls agent methods." Agents are passive data providers;
6	// the dispatcher handles all orchestration: state transitions, strategy calls,
7	// file change detection, metadata generation.
8	package cli
9	
10	import (
11		"context"
12		"errors"
13		"fmt"
14		"log/slog"
15		"os"
16		"path/filepath"
17		"slices"
18		"strings"
19		"time"
20	
21		"github.com/entireio/cli/cmd/entire/cli/agent"
22		"github.com/entireio/cli/cmd/entire/cli/agent/types"
23		"github.com/entireio/cli/cmd/entire/cli/logging"
24		"github.com/entireio/cli/cmd/entire/cli/paths"
25		"github.com/entireio/cli/cmd/entire/cli/review"
26		"github.com/entireio/cli/cmd/entire/cli/session"
27		"github.com/entireio/cli/cmd/entire/cli/strategy"
28		"github.com/entireio/cli/cmd/entire/cli/transcript"
29		"github.com/entireio/cli/cmd/entire/cli/validation"
30		"github.com/entireio/cli/perf"
31	)
