33	// DispatchLifecycleEvent routes a normalized lifecycle event to the appropriate handler.
34	// Returns nil if the event was handled successfully.
35	func DispatchLifecycleEvent(ctx context.Context, ag agent.Agent, event *agent.Event) error {
36		if ag == nil {
37			return errors.New("agent cannot be nil")
38		}
39		if event == nil {
40			return errors.New("event cannot be nil")
41		}
42	
43		switch event.Type {
44		case agent.SessionStart:
45			return handleLifecycleSessionStart(ctx, ag, event)
46		case agent.TurnStart:
47			return handleLifecycleTurnStart(ctx, ag, event)
48		case agent.TurnEnd:
49			return handleLifecycleTurnEnd(ctx, ag, event)
50		case agent.Compaction:
51			return handleLifecycleCompaction(ctx, ag, event)
52		case agent.SessionEnd:
53			return handleLifecycleSessionEnd(ctx, ag, event)
54		case agent.SubagentStart:
55			return handleLifecycleSubagentStart(ctx, ag, event)
56		case agent.SubagentEnd:
57			return handleLifecycleSubagentEnd(ctx, ag, event)
58		case agent.ModelUpdate:
59			return handleLifecycleModelUpdate(ctx, ag, event)
60		default:
61			return fmt.Errorf("unknown lifecycle event type: %d", event.Type)
62		}
63	}
64	
65	// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
66	// fires state machine transition.
67	func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
68		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
69		logging.Info(logCtx, "session-start",
70			slog.String("event", event.Type.String()),
71			slog.String("session_id", event.SessionID),
72			slog.String("session_ref", event.SessionRef),
73			slog.String("model", event.Model),
74		)
75	
76		if event.SessionID == "" {
77			return fmt.Errorf("no session_id in %s event", event.Type)
78		}
79		if err := validation.ValidateSessionID(event.SessionID); err != nil {
80			return fmt.Errorf("invalid %s event: %w", event.Type, err)
81		}
82	
83		// Build informational message — warn early if repo has no commits yet,
84		// since checkpoints require at least one commit to work.
85		message := sessionStartMessage(ag.Name(), false)
86		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
87			message = sessionStartMessage(ag.Name(), true)
88		}
89	
90		// Check for concurrent sessions and append count if any
91		_, countSessionsSpan := perf.Start(ctx, "count_active_sessions")
92		strat := GetStrategy(ctx)
93		if count, err := strat.CountOtherActiveSessionsWithCheckpoints(ctx, event.SessionID); err == nil && count > 0 {
94			if ag.Name() == agent.AgentNameCodex {
95				message += fmt.Sprintf(" %d other active conversation(s) in this workspace will also be included. Use 'entire status' for more information.", count)
96			} else {
97				message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
98			}
99		}
100		countSessionsSpan.End()
101	
102		// Output informational message if the agent supports hook responses.
103		// Claude Code reads JSON from stdout; agents that don't implement
104		// HookResponseWriter silently skip (avoids raw JSON in their terminal).
105		_, hookResponseSpan := perf.Start(ctx, "write_hook_response")
106		if event.ResponseMessage != "" {
107			message = event.ResponseMessage
108		}
109		if writer, ok := agent.AsHookResponseWriter(ag); ok {
110			if err := writer.WriteHookResponse(message); err != nil {
111				hookResponseSpan.RecordError(err)
112				hookResponseSpan.End()
113				return fmt.Errorf("failed to write hook response: %w", err)
114			}
115		}
116		hookResponseSpan.End()
117	
118		// Store model hint if the agent provided model info on SessionStart
119		if event.Model != "" {
120			if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
121				logging.Warn(logCtx, "failed to store model hint on session start",
122					slog.String("error", err.Error()))
123			}
124		}
125	
126		// Fire EventSessionStart for the current session (if state exists).
127		if state, loadErr := strategy.LoadSessionState(ctx, event.SessionID); loadErr != nil {
128			logging.Warn(logCtx, "failed to load session state on start",
129				slog.String("error", loadErr.Error()))
130		} else if state != nil {
131			persistEventMetadataToState(event, state)
132			if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
133				logging.Warn(logCtx, "session start transition failed",
134					slog.String("error", transErr.Error()))
135			}
136			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
137				logging.Warn(logCtx, "failed to update session state on start",
138					slog.String("error", saveErr.Error()))
139			}
140		}
141	
142		return nil
143	}
144	
145	func sessionStartMessage(agentName types.AgentName, emptyRepo bool) string {
146		if agentName == agent.AgentNameCodex {
147			if emptyRepo {
148				return "Entire CLI found no commits yet — checkpoints will activate after your first commit."
149			}
150			return "Entire CLI will link this conversation to your next commit."
151		}
152	
153		if emptyRepo {
154			return "\n\nEntire CLI found no commits yet — checkpoints will activate after your first commit."
155		}
156		return "\n\nEntire CLI will link this conversation to your next commit."
157	}
