159	// handleLifecycleModelUpdate persists the model name for the current session.
160	//
161	// If the session state file already exists (e.g., Gemini's BeforeModel fires
162	// after TurnStart), the model is written directly to state.ModelName — no hint
163	// file needed. Otherwise falls back to StoreModelHint for cross-process
164	// persistence (see its doc comment for the full rationale).
165	func handleLifecycleModelUpdate(ctx context.Context, ag agent.Agent, event *agent.Event) error {
166		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
167		logging.Info(logCtx, "model-update",
168			slog.String("session_id", event.SessionID),
169			slog.String("model", event.Model),
170		)
171	
172		if event.SessionID == "" || event.Model == "" {
173			return nil
174		}
175	
176		// Prefer writing directly to session state when it exists
177		state, loadErr := strategy.LoadSessionState(ctx, event.SessionID)
178		if loadErr != nil {
179			logging.Debug(logCtx, "could not load session state for model update, using hint file",
180				slog.String("error", loadErr.Error()))
181		}
182		if loadErr == nil && state != nil {
183			state.ModelName = event.Model
184			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
185				logging.Warn(logCtx, "failed to update session state with model",
186					slog.String("error", saveErr.Error()))
187			}
188			return nil
189		}
190	
191		// State doesn't exist yet (or failed to load) — use hint file (see StoreModelHint doc)
192		if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
193			logging.Warn(logCtx, "failed to store model hint",
194				slog.String("error", err.Error()))
195		}
196	
197		return nil
198	}
199	
200	// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
201	// ensures strategy setup, initializes session.
202	func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
203		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
204		logging.Info(logCtx, "turn-start",
205			slog.String("event", event.Type.String()),
206			slog.String("session_id", event.SessionID),
207			slog.String("session_ref", event.SessionRef),
208			slog.String("model", event.Model),
209		)
210	
211		sessionID := event.SessionID
212		if sessionID == "" {
213			return fmt.Errorf("no session_id in %s event", event.Type)
214		}
215		if err := validation.ValidateSessionID(sessionID); err != nil {
216			return fmt.Errorf("invalid %s event: %w", event.Type, err)
217		}
218	
219		// Fill model from hint file if the agent didn't provide it on this hook
220		if event.Model == "" {
221			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
222				event.Model = hint
223				logging.Debug(logCtx, "loaded model from hint file",
224					slog.String("model", hint))
225			}
226		}
227	
228		// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
229		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
230		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
231			captureSpan.RecordError(err)
232			captureSpan.End()
233			return err
234		}
235		captureSpan.End()
236	
237		// Append prompt to prompt.txt on filesystem so it's available for
238		// mid-turn commits (before SaveStep writes it to the shadow branch).
239		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
240		if event.Prompt != "" {
241			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
242			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
243				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
244					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
245					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
246					var content string
247					if readErr == nil && len(existing) > 0 {
248						content = string(existing) + "\n\n---\n\n" + event.Prompt
249					} else {
250						content = event.Prompt
251					}
252					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
253						logging.Warn(logCtx, "failed to write prompt.txt",
254							slog.String("error", writeErr.Error()))
255					}
256				}
257			}
258		}
259	
260		// Ensure strategy setup and initialize session
261		_, initSpan := perf.Start(ctx, "init_session")
262		if err := strategy.EnsureSetup(ctx); err != nil {
263			logging.Warn(logCtx, "failed to ensure strategy setup",
264				slog.String("error", err.Error()))
265		}
266	
267		strat := GetStrategy(ctx)
268		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
269			logging.Warn(logCtx, "failed to initialize session state",
270				slog.String("error", err.Error()))
271		}
272	
273		// Best-effort: adopt ENTIRE_REVIEW_* env vars set by `entire review` on
274		// the spawned agent process. Each agent process has its own env, so there
275		// is no file race across worktrees. Errors in load/save must not fail the turn.
276		if state, loadErr := strategy.LoadSessionState(ctx, sessionID); loadErr != nil {
277			logging.Warn(logCtx, "failed to load session state for review env adoption",
278				slog.String("error", loadErr.Error()))
279		} else if state != nil {
280			updated := *state
281			adoptReviewEnv(logCtx, &updated, string(ag.Name()))
282			if updated.Kind != state.Kind || updated.ReviewPrompt != state.ReviewPrompt || !slices.Equal(updated.ReviewSkills, state.ReviewSkills) {
283				if saveErr := strategy.SaveSessionState(ctx, &updated); saveErr != nil {
284					logging.Warn(logCtx, "failed to save session state after review env adoption",
285						slog.String("error", saveErr.Error()))
286				}
287			}
288		}
289		initSpan.End()
290	
291		return nil
292	}
293	
294	// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
295	// detects file changes, saves step + checkpoint, transitions phase.
296	//
297	//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
298	func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
299		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
300		logging.Info(logCtx, "turn-end",
301			slog.String("event", event.Type.String()),
302			slog.String("session_id", event.SessionID),
303			slog.String("session_ref", event.SessionRef),
304			slog.String("model", event.Model),
305		)
306	
307		sessionID := event.SessionID
308		if sessionID == "" {
309			sessionID = unknownSessionID
310		}
311	
312		// Fill model from hint file if the agent didn't provide it on this hook
313		if event.Model == "" && sessionID != unknownSessionID {
314			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
315				event.Model = hint
316				logging.Debug(logCtx, "loaded model from hint file",
317					slog.String("model", hint))
318			}
319		}
320	
321		transcriptRef := event.SessionRef
322		if transcriptRef == "" {
323			return errors.New("transcript file not specified")
324		}
325	
326		// If agent implements TranscriptPreparer, materialize the transcript file.
327		// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
328		// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
329		// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
330		// TranscriptPreparer (Gemini, Droid) are unaffected.
331		_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
332		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
333			if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
334				logging.Warn(logCtx, "failed to prepare transcript",
335					slog.String("error", err.Error()))
336			}
337		}
338	
339		if !fileExists(transcriptRef) {
340			prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
341			prepareSpan.End()
342			return fmt.Errorf("transcript file not found: %s", transcriptRef)
343		}
344	
345		// Early check: bail out quickly if the repo has no commits yet.
346		// Return nil (not an error) so the hook exits 0 — agents treat non-zero
347		// exit codes as hook failures. The user was already warned at session start.
348		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
349			prepareSpan.End()
350			logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
351			return nil
352		}
353		prepareSpan.End()
354	
355		// Create session metadata directory
356		_, copySpan := perf.Start(ctx, "copy_transcript")
357		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
358		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
359		if err != nil {
360			sessionDirAbs = sessionDir
361		}
362		if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
363			copySpan.RecordError(err)
364			copySpan.End()
365			return fmt.Errorf("failed to create session directory: %w", err)
366		}
367	
368		// Copy transcript to session directory
369		transcriptData, err := ag.ReadTranscript(transcriptRef)
370		if err != nil {
371			copySpan.RecordError(err)
372			copySpan.End()
373			return fmt.Errorf("failed to read transcript: %w", err)
374		}
375		logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
376		if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
377			copySpan.RecordError(err)
378			copySpan.End()
379			return fmt.Errorf("failed to write transcript: %w", err)
380		}
381		logging.Debug(logCtx, "copied transcript",
382			slog.String("path", sessionDir+"/"+paths.TranscriptFileName))
383		copySpan.End()
384	
385		// Load pre-prompt state (captured on TurnStart)
386		_, extractSpan := perf.Start(ctx, "extract_metadata")
387		preState, err := LoadPrePromptState(ctx, sessionID)
388		if err != nil {
389			logging.Warn(logCtx, "failed to load pre-prompt state",
390				slog.String("error", err.Error()))
391		}
392	
393		// Determine transcript offset
394		transcriptOffset := resolveTranscriptOffset(ctx, preState, sessionID)
395	
396		// Backfill prompt.txt from transcript when prompt data is missing.
397		// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
398		// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
399		// there genuinely were no prompts. We track whether backfill occurred so we can
400		// update session state after SaveStep (which may reinitialize state).
401		var backfilledPrompt string
402		promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
403		existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
404		if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
405			logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
406				slog.String("error", readPromptErr.Error()))
407		} else if len(existingPrompt) == 0 {
408			if extractor, ok := agent.AsPromptExtractor(ag); ok {
409				prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
410				if extractErr != nil {
411					logging.Warn(logCtx, "failed to extract prompts from transcript",
412						slog.String("error", extractErr.Error()))
413				} else if len(prompts) > 0 {
414					content := strings.Join(prompts, "\n\n---\n\n")
415					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
416						logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
417							slog.String("error", writeErr.Error()))
418					} else {
419						logging.Debug(logCtx, "backfilled prompt.txt from transcript",
420							slog.Int("prompt_count", len(prompts)))
421						backfilledPrompt = prompts[len(prompts)-1]
422					}
423				}
424			}
425		}
426	
427		// Compute subagents directory for agents that support subagent extraction.
428		// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
429		subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
430	
431		// Extract metadata via agent interface (modified files)
432		var modifiedFiles []string
433	
434		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
435			// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
436			if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
437				if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
438					logging.Warn(logCtx, "failed to extract modified files (with subagents)",
439						slog.String("error", fileErr.Error()))
440				} else {
441					modifiedFiles = files
442				}
443			} else {
444				// Fall back to basic extraction (main transcript only)
445				if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
446					logging.Warn(logCtx, "failed to extract modified files",
447						slog.String("error", fileErr.Error()))
448				} else {
449					modifiedFiles = files
450				}
451			}
452		}
453		extractSpan.End()
454	
455		// Generate commit message from last prompt (read from session state, set at TurnStart).
456		// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
457		// Fall back to backfilledPrompt extracted from the transcript.
458		// Single load serves both prompt retrieval and backfill.
459		_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
460		lastPrompt := ""
461		if sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && sessionState != nil {
462			lastPrompt = sessionState.LastPrompt
463			// Backfill LastPrompt so `entire status` shows the prompt even when
464			// no files were modified (before the early return below).
465			if lastPrompt == "" && backfilledPrompt != "" {
466				lastPrompt = backfilledPrompt
467				sessionState.LastPrompt = backfilledPrompt
468				if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
469					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
470						slog.String("error", saveErr.Error()))
471				}
472			}
473		} else if backfilledPrompt != "" {
474			lastPrompt = backfilledPrompt
475		}
476		commitMessage := generateCommitMessage(lastPrompt, ag.Type())
477		logging.Debug(logCtx, "using commit message",
478			slog.Int("message_length", len(commitMessage)))
479		commitMsgSpan.End()
480	
481		// Get worktree root for path normalization
482		_, detectSpan := perf.Start(ctx, "detect_file_changes")
483		repoRoot, err := paths.WorktreeRoot(ctx)
484		if err != nil {
485			detectSpan.RecordError(err)
486			detectSpan.End()
487			return fmt.Errorf("failed to get worktree root: %w", err)
488		}
489	
490		var preUntrackedFiles []string
491		if preState != nil {
492			logging.Debug(logCtx, "pre-prompt state",
493				slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
494			preUntrackedFiles = preState.PreUntrackedFiles()
495		}
496	
497		// Detect file changes via git status
498		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
499		if err != nil {
500			logging.Warn(logCtx, "failed to compute file changes",
501				slog.String("error", err.Error()))
502		}
503		detectSpan.End()
504	
505		// Filter and normalize all paths
506		_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
507		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
508		var relNewFiles, relDeletedFiles []string
509		if changes != nil {
510			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
511			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
512	
513			// Merge git-status modified files as a fallback for transcript parsing.
514			// Transcript parsing is the primary source for modified files, but it can miss
515			// files if the agent uses an unrecognized tool or the transcript format changes.
516			// Git status catches any tracked file with working-tree changes.
517			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
518		}
519	
520		// Filter transcript-extracted files to exclude files already committed to HEAD.
521		// When an agent commits files mid-turn, those files are condensed by PostCommit
522		// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
523		// if it exists in HEAD with the same content as the working tree.
524		relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
525		normalizeSpan.End()
526	
527		// Check if there are any changes
528		totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
529		if totalChanges == 0 {
530			logging.Info(logCtx, "no files modified during session, skipping checkpoint")
531			transitionSessionTurnEnd(ctx, sessionID, event)
532			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
533				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
534					slog.String("error", cleanupErr.Error()))
535			}
536			return nil
537		}
538	
539		// Log file changes
540		logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)
541	
542		// Get git author
543		author, err := GetGitAuthor(ctx)
544		if err != nil {
545			return fmt.Errorf("failed to get git author: %w", err)
546		}
547	
548		// Get strategy and agent type
549		strat := GetStrategy(ctx)
550		agentType := ag.Type()
551	
552		// Get transcript position/identifier from pre-prompt state
553		var transcriptIdentifierAtStart string
554		var transcriptLinesAtStart int
555		if preState != nil {
556			transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
557			transcriptLinesAtStart = preState.TranscriptOffset
558		}
559	
560		// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
561		tokenUsage := agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)
562	
563		// Build fully-populated step context and delegate to strategy
564		stepCtx := strategy.StepContext{
565			SessionID:                sessionID,
566			ModifiedFiles:            relModifiedFiles,
567			NewFiles:                 relNewFiles,
568			DeletedFiles:             relDeletedFiles,
569			MetadataDir:              sessionDir,
570			MetadataDirAbs:           sessionDirAbs,
571			CommitMessage:            commitMessage,
572			TranscriptPath:           transcriptRef,
573			AuthorName:               author.Name,
574			AuthorEmail:              author.Email,
575			AgentType:                agentType,
576			StepTranscriptIdentifier: transcriptIdentifierAtStart,
577			StepTranscriptStart:      transcriptLinesAtStart,
578			TokenUsage:               tokenUsage,
579		}
580	
581		if err := strat.SaveStep(ctx, stepCtx); err != nil {
582			return fmt.Errorf("failed to save step: %w", err)
583		}
584	
585		// Update session state with backfilled prompt after SaveStep.
586		// Done after SaveStep because SaveStep may reinitialize session state,
587		// which would overwrite an earlier LastPrompt update.
588		if backfilledPrompt != "" {
589			if state, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && state != nil && state.LastPrompt == "" {
590				state.LastPrompt = backfilledPrompt
591				if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
592					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
593						slog.String("error", saveErr.Error()))
594				}
595			}
596		}
597	
598		// Transition session phase and cleanup
599		transitionSessionTurnEnd(ctx, sessionID, event)
600		if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
601			logging.Warn(logCtx, "failed to cleanup pre-prompt state",
602				slog.String("error", cleanupErr.Error()))
603		}
604	
605		return nil
606	}
607	
608	// handleLifecycleCompaction handles context compaction: saves current progress
609	// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
610	// Also resets the transcript offset since the transcript may be truncated.
611	func handleLifecycleCompaction(ctx context.Context, ag agent.Agent, event *agent.Event) error {
612		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
613		logging.Info(logCtx, "compaction",
614			slog.String("event", event.Type.String()),
615			slog.String("session_id", event.SessionID),
616		)
617	
618		// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
619		sessionID := event.SessionID
620		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
621		if loadErr != nil {
622			logging.Warn(logCtx, "failed to load session state for compaction",
623				slog.String("error", loadErr.Error()))
624		}
625		if sessionState != nil {
626			persistEventMetadataToState(event, sessionState)
627	
628			if transErr := strategy.TransitionAndLog(ctx, sessionState, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
629				logging.Warn(logCtx, "compaction transition failed",
630					slog.String("error", transErr.Error()))
631			}
632	
633			if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
634				logging.Warn(logCtx, "failed to save session state after compaction",
635					slog.String("error", saveErr.Error()))
636			}
637		}
638	
639		logging.Info(logCtx, "context compaction detected")
640		return nil
641	}
