643	// handleLifecycleSessionEnd handles session end: marks the session as ended.
644	func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
645		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
646		logging.Info(logCtx, "session-end",
647			slog.String("event", event.Type.String()),
648			slog.String("session_id", event.SessionID),
649		)
650	
651		if event.SessionID == "" {
652			return nil // No session to update
653		}
654	
655		// Note: We intentionally don't clean up cached transcripts here.
656		// Post-session commits (carry-forward in ENDED phase) may still need
657		// the transcript to extract file changes. Cleanup is handled by
658		// `entire clean` or when the session state is fully removed.
659	
660		if err := markSessionEnded(ctx, event, event.SessionID); err != nil {
661			logging.Warn(logCtx, "failed to mark session ended",
662				slog.String("error", err.Error()))
663			// Don't attempt eager condense if we couldn't even mark the session ended —
664			// the session state may be in an inconsistent state.
665			return nil
666		}
667	
668		// Eagerly condense session data so PostCommit doesn't have to process it.
669		// This prevents zombie ENDED sessions from accumulating and causing O(N)
670		// overhead on every future commit (GitHub issue #591).
671		// Fail-open: if this fails, PostCommit will still process it on the next commit.
672		strat := GetStrategy(ctx)
673		if err := strat.CondenseAndMarkFullyCondensed(ctx, event.SessionID); err != nil {
674			logging.Warn(logCtx, "eager condense on session stop failed",
675				slog.String("session_id", event.SessionID),
676				slog.String("error", err.Error()))
677		}
678	
679		return nil
680	}
