700	// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
701	func handleLifecycleSubagentEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
702		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
703		if event.SubagentType == "" && event.TaskDescription == "" {
704			// Extract subagent type and description from tool input
705			event.SubagentType, event.TaskDescription = ParseSubagentTypeAndDescription(event.ToolInput)
706		}
707	
708		// Determine subagent transcript path
709		transcriptDir := filepath.Dir(event.SessionRef)
710		var subagentTranscriptPath string
711		if event.SubagentID != "" {
712			subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
713			if !fileExists(subagentTranscriptPath) {
714				subagentTranscriptPath = ""
715			}
716		}
717	
718		// Log context
719		subagentEndAttrs := []any{
720			slog.String("event", event.Type.String()),
721			slog.String("session_id", event.SessionID),
722			slog.String("tool_use_id", event.ToolUseID),
723		}
724		if event.SubagentID != "" {
725			subagentEndAttrs = append(subagentEndAttrs, slog.String("agent_id", event.SubagentID))
726		}
727		if subagentTranscriptPath != "" {
728			subagentEndAttrs = append(subagentEndAttrs, slog.String("subagent_transcript", subagentTranscriptPath))
729		}
730		logging.Info(logCtx, "subagent completed", subagentEndAttrs...)
731	
732		// Extract modified files from hook payload and/or subagent transcript
733		var modifiedFiles []string
734		modifiedFiles = append(modifiedFiles, event.ModifiedFiles...)
735		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
736			transcriptToScan := event.SessionRef
737			if subagentTranscriptPath != "" {
738				transcriptToScan = subagentTranscriptPath
739			}
740			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
741				logging.Warn(logCtx, "failed to extract modified files from subagent",
742					slog.String("error", fileErr.Error()))
743			} else {
744				modifiedFiles = mergeUnique(modifiedFiles, files)
745			}
746		}
747	
748		// Load pre-task state and detect file changes.
749		// If no pre-task state exists (agent doesn't support pre-task hook), fall back
750		// to the session's pre-prompt state. Without either, DetectFileChanges receives
751		// nil and treats ALL untracked files as new — which would create spurious task
752		// checkpoints for pre-existing untracked files (e.g., .github/hooks/entire.json).
753		preState, err := LoadPreTaskState(ctx, event.ToolUseID)
754		if err != nil {
755			logging.Warn(logCtx, "failed to load pre-task state",
756				slog.String("error", err.Error()))
757		}
758		var preUntrackedFiles []string
759		if preState != nil {
760			preUntrackedFiles = preState.PreUntrackedFiles()
761		}
762		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
763		if err != nil {
764			logging.Warn(logCtx, "failed to compute file changes",
765				slog.String("error", err.Error()))
766		}
767	
768		// Get worktree root and normalize paths
769		repoRoot, err := paths.WorktreeRoot(ctx)
770		if err != nil {
771			return fmt.Errorf("failed to get worktree root: %w", err)
772		}
773	
774		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
775		var relNewFiles, relDeletedFiles []string
776		if changes != nil {
777			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
778			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
779			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
780		}
781	
782		// If no changes, skip
783		if len(relModifiedFiles) == 0 && len(relNewFiles) == 0 && len(relDeletedFiles) == 0 {
784			logging.Info(logCtx, "no file changes detected, skipping task checkpoint")
785			_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
786			return nil
787		}
788	
789		// Find checkpoint UUID from main transcript (best-effort)
790		var checkpointUUID string
791		// Use the existing CLI-level checkpoint UUID finder
792		mainLines, _ := parseTranscriptForCheckpointUUID(event.SessionRef) //nolint:errcheck // best-effort
793		if mainLines != nil {
794			checkpointUUID, _ = FindCheckpointUUID(mainLines, event.ToolUseID)
795		}
796	
797		// Get git author
798		author, err := GetGitAuthor(ctx)
799		if err != nil {
800			return fmt.Errorf("failed to get git author: %w", err)
801		}
802	
803		// Build task checkpoint context
804		strat := GetStrategy(ctx)
805		agentType := ag.Type()
806	
807		taskStepCtx := strategy.TaskStepContext{
808			SessionID:              event.SessionID,
809			ToolUseID:              event.ToolUseID,
810			AgentID:                event.SubagentID,
811			ModifiedFiles:          relModifiedFiles,
812			NewFiles:               relNewFiles,
813			DeletedFiles:           relDeletedFiles,
814			TranscriptPath:         event.SessionRef,
815			SubagentTranscriptPath: subagentTranscriptPath,
816			CheckpointUUID:         checkpointUUID,
817			AuthorName:             author.Name,
818			AuthorEmail:            author.Email,
819			SubagentType:           event.SubagentType,
820			TaskDescription:        event.TaskDescription,
821			AgentType:              agentType,
822		}
823	
824		if err := strat.SaveTaskStep(ctx, taskStepCtx); err != nil {
825			return fmt.Errorf("failed to save task step: %w", err)
826		}
827	
828		_ = CleanupPreTaskState(ctx, event.ToolUseID) //nolint:errcheck // best-effort cleanup
829		return nil
830	}
