834	// resolveTranscriptOffset determines the transcript offset to use for parsing.
835	// Prefers pre-prompt state, falls back to session state.
836	func resolveTranscriptOffset(ctx context.Context, preState *PrePromptState, sessionID string) int {
837		logCtx := logging.WithComponent(ctx, "lifecycle")
838		if preState != nil && preState.TranscriptOffset > 0 {
839			logging.Debug(logCtx, "pre-prompt state found, parsing transcript from offset",
840				slog.Int("offset", preState.TranscriptOffset))
841			return preState.TranscriptOffset
842		}
843	
844		// Fall back to session state
845		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
846		if loadErr != nil {
847			logging.Warn(logCtx, "failed to load session state",
848				slog.String("error", loadErr.Error()))
849			return 0
850		}
851		if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
852			logging.Debug(logCtx, "session state found, parsing transcript from offset",
853				slog.Int("offset", sessionState.CheckpointTranscriptStart))
854			return sessionState.CheckpointTranscriptStart
855		}
856	
857		return 0
858	}
