860	// parseTranscriptForCheckpointUUID is a thin wrapper around transcript parsing for checkpoint UUID lookup.
861	// Returns parsed transcript lines for use with FindCheckpointUUID.
862	func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, error) {
863		lines, err := transcript.ParseFromFileAtLine(transcriptPath, 0)
864		if err != nil {
865			return nil, fmt.Errorf("parsing transcript for checkpoint UUID: %w", err)
866		}
867		return lines, nil
868	}
