870	// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
871	func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event) {
872		logCtx := logging.WithComponent(ctx, "lifecycle")
873		turnState, loadErr := strategy.LoadSessionState(ctx, sessionID)
874		if loadErr != nil {
875			logging.Warn(logCtx, "failed to load session state for turn end",
876				slog.String("error", loadErr.Error()))
877			return
878		}
879		if turnState == nil {
880			return
881		}
882	
883		persistEventMetadataToState(event, turnState)
884	
885		if err := strategy.TransitionAndLog(ctx, turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
886			logging.Warn(logCtx, "turn-end transition failed",
887				slog.String("error", err.Error()))
888		}
889	
890		// Always dispatch to strategy for turn-end handling. The strategy reads
891		// work items from state (e.g. TurnCheckpointIDs), not the action list.
892		strat := GetStrategy(ctx)
893		if err := strat.HandleTurnEnd(ctx, turnState); err != nil {
894			logging.Warn(logCtx, "turn-end action dispatch failed",
895				slog.String("error", err.Error()))
896		}
897	
898		if updateErr := strategy.SaveSessionState(ctx, turnState); updateErr != nil {
899			logging.Warn(logCtx, "failed to update session phase on turn end",
900				slog.String("error", updateErr.Error()))
901		}
902	}
