904	// markSessionEnded transitions the session to ENDED phase via the state machine.
905	// If event is non-nil, hook-provided metrics are persisted to state before saving.
906	func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string) error {
907		state, err := strategy.LoadSessionState(ctx, sessionID)
908		if err != nil {
909			return fmt.Errorf("failed to load session state: %w", err)
910		}
911		if state == nil {
912			return nil // No state file, nothing to update
913		}
914	
915		if event != nil {
916			persistEventMetadataToState(event, state)
917		}
918	
919		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
920			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
921				slog.String("error", transErr.Error()))
922		}
923	
924		now := time.Now()
925		state.EndedAt = &now
926	
927		if err := strategy.SaveSessionState(ctx, state); err != nil {
928			return fmt.Errorf("failed to save session state: %w", err)
929		}
930		return nil
931	}
