933	// logFileChanges logs the files modified, created, and deleted during a session.
934	func logFileChanges(ctx context.Context, modified, newFiles, deleted []string) {
935		logCtx := logging.WithComponent(ctx, "lifecycle")
936		logging.Debug(logCtx, "files changed during session",
937			slog.Int("modified", len(modified)),
938			slog.Int("new", len(newFiles)),
939			slog.Int("deleted", len(deleted)))
940	}
941	
942	func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) {
943		// Update ModelName if provided (model is known by turn-end even on first turn)
944		if event.Model != "" {
945			state.ModelName = event.Model
946		}
947	
948		// Persist hook-provided session metrics (e.g., from Cursor hooks)
949		if event.DurationMs > 0 {
