969	// adoptReviewEnv tags the session as a review session when ENTIRE_REVIEW_*
970	// env vars are present on the current process. `entire review` sets these
971	// vars on the spawned agent process; the lifecycle hook (a child of the agent)
972	// inherits them naturally. Agent and starting-SHA checks protect against stale
973	// ENTIRE_REVIEW_* values inherited from a parent shell or a nested invocation.
974	//
975	// Adoption is idempotent: if state.Kind is already set (subsequent turns of
976	// a review session) the function returns without modifying state.
977	//
978	// Failure modes are silent at the user level but logged for diagnostics:
979	//   - EnvSession unset or not "1": not a review session; return, no tagging.
980	//   - EnvAgent does not match the hook agent: leave session untagged.
981	//   - EnvStartingSHA does not match the session base commit: leave untagged.
982	//   - EnvSkills malformed JSON: log warning, leave session untagged to avoid
983	//     corrupting metadata with junk data.
984	func adoptReviewEnv(ctx context.Context, state *session.State, expectedAgent string) {
985		// Already tagged — don't re-apply on subsequent turns.
986		if state.Kind != "" {
987			return
988		}
989		if os.Getenv(review.EnvSession) != "1" {
990			return
991		}
992		envAgent := os.Getenv(review.EnvAgent)
993		if envAgent != expectedAgent {
994			logging.Warn(ctx, "review env adoption skipped: agent mismatch",
995				slog.String("env_agent", envAgent),
996				slog.String("hook_agent", expectedAgent))
997			return
998		}
999		startingSHA := os.Getenv(review.EnvStartingSHA)
1000		if startingSHA == "" || state.BaseCommit == "" || startingSHA != state.BaseCommit {
1001			logging.Warn(ctx, "review env adoption skipped: starting SHA mismatch",
1002				slog.String("env_starting_sha", startingSHA),
1003				slog.String("state_base_commit", state.BaseCommit))
1004			return
1005		}
1006		skills, err := review.DecodeSkills(os.Getenv(review.EnvSkills))
1007		if err != nil {
1008			logging.Warn(ctx, "review env adoption failed: invalid skills JSON",
1009				slog.String("err", err.Error()))
1010			return
1011		}
1012		state.Kind = session.KindAgentReview
1013		state.ReviewSkills = skills
1014		state.ReviewPrompt = os.Getenv(review.EnvPrompt)
1015		logging.Debug(ctx, "adopted review env",
1016			slog.String("agent", envAgent),
1017			slog.Int("skill_count", len(skills)))
1018	}
