+
+func isReviewSpawnEnvEntry(kv string) bool {
+	for _, prefix := range []string{
+		reviewenv.EnvSession + "=",
+		reviewenv.EnvAgent + "=",
+		reviewenv.EnvSkills + "=",
+		reviewenv.EnvPrompt + "=",
+		reviewenv.EnvStartingSHA + "=",
+	} {
+		if strings.HasPrefix(kv, prefix) {
+			return true
+		}
+	}
+	return false
+}
