// headHasReviewCheckpoint checks whether HEAD's checkpoint metadata includes
// a review session. Returns (true, infoString) if HasReview is set.
// Single lookup: read the Entire-Checkpoint trailer from HEAD, then resolve
// the CheckpointSummary via ResolveCommittedReaderForCheckpoint so v2-enabled
// repos also work (v1 alone would miss v2-written summaries).
func headHasReviewCheckpoint(ctx context.Context) (bool, string) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Debug(ctx, "head review check: locate worktree root", slog.String("error", err.Error()))
		return false, ""
	}
	execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "-1", "--format=%B")
	output, err := execCmd.Output()
	if err != nil {
		logging.Debug(ctx, "head review check: read HEAD commit message", slog.String("error", err.Error()))
		return false, ""
	}
	cpID, ok := trailers.ParseCheckpoint(string(output))
	if !ok {
		logging.Debug(ctx, "head review check: no Entire-Checkpoint trailer on HEAD")
		return false, ""
	}
	repo, err := git.PlainOpen(repoRoot)
	if err != nil {
		logging.Debug(ctx, "head review check: open repository", slog.String("error", err.Error()))
		return false, ""
	}
	v1Store := checkpoint.NewGitStore(repo)
	v2URL, urlErr := remote.FetchURL(ctx)
	if urlErr != nil {
		logging.Debug(ctx, "head review check: no configured v2 fetch remote", slog.String("error", urlErr.Error()))
		v2URL = ""
	}
	v2Store := checkpoint.NewV2GitStore(repo, v2URL)
	_, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, cpID, v1Store, v2Store, settings.IsCheckpointsV2Enabled(ctx))
	if err != nil || summary == nil {
		logging.Debug(ctx, "head review check: resolve checkpoint summary",
			slog.String("checkpoint_id", cpID.String()),
			slog.Any("error", err))
		return false, ""
	}
	if !summary.HasReview {
		logging.Debug(ctx, "head review check: summary HasReview is false", slog.String("checkpoint_id", cpID.String()))
		return false, ""
	}
	return true, fmt.Sprintf("checkpoint %s", cpID)
}

// newReviewAttachCmd is a thin wrapper around `entire attach --review`. It
// shares all wiring with runAttach; only the UX surface differs, letting
// users discover review-attach through `entire review` in help output.
//
// Migrated from the old review.go. Kept here (not in review/ subpackage)
// because it calls runAttachSurfaceReviewErrors which is in the cli package.
func newReviewAttachCmd() *cobra.Command {
	var (
		force      bool
		agentFlag  string
		skillsFlag []string
	)
	cmd := &cobra.Command{
		Use:   "attach <session-id>",
		Short: "Tag an existing agent session as a review",
		Long: `Tag an existing agent session as an agent_review and link it to
the current commit's checkpoint. Use this when you ran a review manually

	//     first configured agent isn't installed but exactly one other is —
	//     without this, SelectReviewAgent would default to the alphabetical
	//     first and the verify-hooks check below would error needlessly.
	//   - 2+ eligible: prompt.
	installed := deps.GetAgentsWithHooksInstalled(ctx)
	if agentOverride == "" {
		eligible := ComputeEligibleConfigured(s, installed)
		switch {
		case len(eligible) == 1:
			agentOverride = eligible[0].Name
		case len(eligible) > 1:
			fn := innerDeps.promptForAgentFn
			if fn == nil {
				fn = PromptForAgent
			}
			picked, pickErr := fn(ctx, eligible)
			if pickErr != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), pickErr.Error())
				return silentErr(pickErr)
			}
			if picked == "" {
				// Defensive: empty picker return must not fall through to
				// alphabetical-first default.
				cmd.SilenceUsage = true
				emptyErr := errors.New("agent picker returned empty agent name")
				fmt.Fprintln(cmd.ErrOrStderr(), emptyErr.Error())
				return silentErr(emptyErr)
			}
			agentOverride = picked
		}
	}

	agentName, cfg, err := SelectReviewAgent(s.Review, agentOverride)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return silentErr(err)
	}

	// 3.5. Verify hooks are installed for the selected agent.
	installedNames := make([]types.AgentName, len(installed))
	copy(installedNames, installed)
	found := false
	for _, n := range installedNames {
		if string(n) == agentName {
			found = true
			break
		}
	}
	if !found {
		cmd.SilenceUsage = true
		fmt.Fprintf(cmd.ErrOrStderr(),
			"Hooks are not installed for %q. Run `entire configure --agent %s` first, "+
				"or remove %q from review settings.\n",
			agentName, agentName, agentName)
		return silentErr(fmt.Errorf("hooks not installed for %s", agentName))
	}

	// 3.6. Verify configured skills are actually installed on disk.
	ag, agErr := agent.Get(types.AgentName(agentName))
	if agErr != nil {
		return fmt.Errorf("resolve agent %s: %w", agentName, agErr)
	}
	if err := VerifyConfiguredSkillsInstalled(ctx, ag, cfg); err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return silentErr(err)
	}

	// 4. Re-run guard: check if HEAD's checkpoint already has a review.
	if reviewed, meta := deps.HeadHasReviewCheckpoint(ctx); reviewed {
		var proceed bool
		form := newAccessibleForm(huh.NewGroup(
			huh.NewConfirm().
				Title(fmt.Sprintf("Already reviewed: %s. Proceed anyway?", meta)).
				Value(&proceed),
		))
		if err := form.RunWithContext(ctx); err != nil {
			fmt.Fprintln(out, "prompt cancelled")
			return err //nolint:wrapcheck // propagate huh cancellation
		}
		if !proceed {
			fmt.Fprintln(out, "Review cancelled.")
			return nil
		}
	}

	// 5. Resolve HEAD SHA and worktree root.
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve worktree root: %w", err)
	}

	// 6. Resolve HEAD SHA and detect scope. Scope work happens BEFORE the
	// launchability branch so non-launchable agents (cursor, opencode,
	// factoryai-droid) also see the scope banner and get a scope-aware
	// prompt persisted to the marker — same context the launchable path
	// passes to Run(). Best-effort: scope detection failure prints no
	// banner and leaves ScopeBaseRef empty.
	headSHA, shaErr := currentHeadSHA(ctx, worktreeRoot)
	if shaErr != nil {
		return fmt.Errorf("resolve HEAD: %w", shaErr)
	}

	// Compute scope via the canonical scope.go path: closest non-self
	// ancestor branch by tip timestamp, fallback chain, full ScopeStats
	// (commits + files changed + uncommitted). Best-effort: scope detection
	// failure prints no banner and leaves ScopeBaseRef empty so the run
	// proceeds with the agent picking its own scope (degraded mode).
	var scopeBaseRef string
	if repo, openErr := git.PlainOpen(worktreeRoot); openErr == nil {
		if stats, statsErr := ComputeScopeStats(ctx, repo); statsErr == nil {
			scopeBaseRef = stats.BaseRef
			fmt.Fprintln(out, formatScopeBanner(stats))
		} else {
			logging.Debug(ctx, "review scope detection failed", slog.String("error", statsErr.Error()))
		}
	} else {
		logging.Debug(ctx, "review repo open failed", slog.String("error", openErr.Error()))
	}

	runCfg := reviewtypes.RunConfig{
		PromptOverride: cfg.Prompt,
		Skills:         cfg.Skills,
		ScopeBaseRef:   scopeBaseRef,
		StartingSHA:    headSHA,
	}

	// 7. Branch on launchability.
	reviewer := deps.ReviewerFor(agentName)
	if reviewer == nil {
		// Non-launchable: write marker (with scope-aware prompt) and print guidance.
		return RunMarkerFallback(ctx, agentName, runCfg, worktreeRoot, out)
	}

	_, waitErr := Run(ctx, reviewer, runCfg, []reviewtypes.Sink{DumpSink{W: out}})
	if waitErr != nil && ctx.Err() == nil {
		// Non-cancellation error: surface to caller.
		return fmt.Errorf("review run: %w", waitErr)
	}
	return nil
}

// currentHeadSHA returns the current HEAD commit hash as a 40-char hex string.
func currentHeadSHA(ctx context.Context, repoRoot string) (string, error) {
	out, err := runGit(ctx, repoRoot, "rev-parse", "HEAD")
	if err != nil {
		return "", fmt.Errorf("git rev-parse HEAD: %w", err)
	}
	return strings.TrimSpace(out), nil
}

			slog.String("error", err.Error()))
	}

	// Best-effort: adopt ENTIRE_REVIEW_* env vars set by `entire review` on
	// the spawned agent process. Each agent process has its own env, so there
	// is no file race across worktrees. Errors in load/save must not fail the turn.
	if state, loadErr := strategy.LoadSessionState(ctx, sessionID); loadErr != nil {
		logging.Warn(logCtx, "failed to load session state for review env adoption",
			slog.String("error", loadErr.Error()))
	} else if state != nil {
		updated := *state
		adoptReviewEnv(logCtx, &updated)
		if updated.Kind != state.Kind || updated.ReviewPrompt != state.ReviewPrompt || !slices.Equal(updated.ReviewSkills, state.ReviewSkills) {
			if saveErr := strategy.SaveSessionState(ctx, &updated); saveErr != nil {
				logging.Warn(logCtx, "failed to save session state after review env adoption",
					slog.String("error", saveErr.Error()))
			}
		}
	}
	initSpan.End()

	return nil
}

// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
// detects file changes, saves step + checkpoint, transitions phase.
//
//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "turn-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
		slog.String("model", event.Model),
	)

	sessionID := event.SessionID
	if sessionID == "" {
		sessionID = unknownSessionID
	}

		state.ContextWindowSize = event.ContextWindowSize
	}
}

// adoptReviewEnv tags the session as a review session when ENTIRE_REVIEW_*
// env vars are present on the current process. `entire review` sets these
// vars on the spawned agent process; the lifecycle hook (a child of the agent)
// inherits them naturally. No file marker, no worktree race, no scoping guard.
//
// Adoption is idempotent: if state.Kind is already set (subsequent turns of
// a review session) the function returns without modifying state.
//
// Failure modes are silent at the user level but logged for diagnostics:
//   - EnvSession unset or not "1": not a review session; return, no tagging.
//   - EnvSkills malformed JSON: log warning, leave session untagged to avoid
//     corrupting metadata with junk data.
func adoptReviewEnv(ctx context.Context, state *session.State) {
	// Already tagged — don't re-apply on subsequent turns.
	if state.Kind != "" {
		return
	}
	if os.Getenv(review.EnvSession) != "1" {
		return
	}
	skills, err := review.DecodeSkills(os.Getenv(review.EnvSkills))
	if err != nil {
		logging.Warn(ctx, "review env adoption failed: invalid skills JSON",
			slog.String("err", err.Error()))
		return
	}
	state.Kind = session.KindAgentReview
	state.ReviewSkills = skills
	state.ReviewPrompt = os.Getenv(review.EnvPrompt)
	logging.Debug(ctx, "adopted review env",
		slog.String("agent", os.Getenv(review.EnvAgent)),
		slog.Int("skill_count", len(skills)))
}

