	// parsed events from another goroutine may block while sending.
	Wait() error
}

// RunConfig is the immutable per-run configuration passed to AgentReviewer.Start.
//
// All fields are optional from a marshalling standpoint (zero value is valid),
// but Skills is typically non-empty in practice — it carries the skill
// invocations (e.g., "/pr-review-toolkit:review-pr") the configured agent
// should run.
type RunConfig struct {
	// PromptOverride, when non-empty, is the exact prompt sent to the agent.
	// It preserves settings.ReviewConfig.Prompt's existing verbatim-override
	// contract: configured skills are still recorded as structured metadata,
	// but they are not prepended to the prompt text.
	PromptOverride string

	// Skills are skill invocation strings passed to the agent verbatim.
	Skills []string

	// AlwaysPrompt is the per-agent always-prompt configured in settings.
	// Concatenated with Skills + PerRunPrompt + a scope clause to form the
	// composed agent prompt.
	AlwaysPrompt string

	// PerRunPrompt is optional textarea input from a single invocation.
	PerRunPrompt string

	// ScopeBaseRef is the git ref the review is scoped against (typically the
	// closest ancestor branch). Used to compose the scope clause and as the
	// base for `git diff` operations the agent may perform.
	ScopeBaseRef string

	// StartingSHA is HEAD at invocation time, propagated to the lifecycle
	// hook via ENTIRE_REVIEW_STARTING_SHA so checkpoint metadata records
	// the commit that was reviewed.
	StartingSHA string
}

// Event is the sealed sum type emitted by Process.Events. The unexported

// Package review — see env.go for package-level rationale.
//
// prompt.go implements the shared prompt composer used by all per-agent
// reviewers. The scope clause pins agents to "commits unique to this branch
// vs the closest ancestor" — preventing the divergent-default problem where
// codex defaulted to origin/main...HEAD and claude defaulted to
// working-tree-only on the same invocation (regression class from #1018
// commit b9ed9c074; enforced structurally here).
package review

import (
	"strings"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// ComposeReviewPrompt assembles the prompt sent to the agent. It joins
// the configured skill invocations, the always-prompt, the per-run
// prompt, and a scope clause that pins the agent to commits unique
// to the current branch vs the closest ancestor.
//
// Empty sections are skipped (no triple-newline gaps). The scope clause
// is only added when cfg.ScopeBaseRef is non-empty.
func ComposeReviewPrompt(cfg reviewtypes.RunConfig) string {
	if cfg.PromptOverride != "" {
		return cfg.PromptOverride
	}

	var sections []string

	// Skills: one per line, joined as a single section.
	if len(cfg.Skills) > 0 {
		sections = append(sections, strings.Join(cfg.Skills, "\n"))
	}

	// AlwaysPrompt and PerRunPrompt: each is its own section if non-empty after trim.
	if trimmed := strings.TrimRight(cfg.AlwaysPrompt, "\n\r "); trimmed != "" {
		sections = append(sections, trimmed)
	}
	if trimmed := strings.TrimRight(cfg.PerRunPrompt, "\n\r "); trimmed != "" {
		sections = append(sections, trimmed)
	}

	// Scope clause: only when a base ref was detected.
	if cfg.ScopeBaseRef != "" {
		sections = append(sections, "Scope: review only the commits unique to this branch vs "+cfg.ScopeBaseRef+".")
	}

	return strings.Join(sections, "\n\n")
}

