func (p *templateProcess) Wait() error {
	if p.stderrDone != nil {
		<-p.stderrDone
	}
	err := p.cmd.Wait()
	if err != nil && p.ctx.Err() != nil {
		return p.ctx.Err() //nolint:wrapcheck // preserve Process cancellation contract
	}
	if err != nil {
