	for i, st := range states {
		var status reviewtypes.AgentStatus
		if st.startErr != nil {
			status = classifyStatus(ctx, st.startErr, eventOutcome{})
		} else {
			status = classifyStatus(ctx, st.waitErr, eventOutcome{
				finishedSeen: st.finishedSeen,
				finishedOk:   st.finishedOk,
				sawRunError:  st.sawRunError,
			})
		}
		agentErr := st.startErr
		if agentErr == nil {
			agentErr = st.waitErr
		}
		agentRuns[i] = reviewtypes.AgentRun{
			Name:      st.name,
			Status:    status,
			Tokens:    st.tokens,
			Buffer:    st.buffer,
			StartedAt: st.startedAt,
			Duration:  st.finishedAt.Sub(st.startedAt),
			Err:       agentErr,
		}
		if firstErr == nil && agentErr != nil && status != reviewtypes.AgentStatusCancelled {
			firstErr = agentErr
		}
	}

	summary := reviewtypes.RunSummary{
		StartedAt:  started,
		FinishedAt: finished,
		Cancelled:  cancelled,
		AgentRuns:  agentRuns,
	}
	for _, sink := range sinks {
		sink.RunFinished(summary)
	}

	return summary, firstErr
}

// Package review — see env.go for package-level rationale.
//
// tui_sink.go provides TUISink, a Sink implementation that renders a Bubble
// Tea status dashboard during a multi-agent review run and supports Ctrl+O
// drill-in mode for inspecting one agent's live event buffer. Used in
// interactive (TTY) multi-agent runs; non-TTY runs and single-agent runs use
// DumpSink instead.
package review

import (
	"context"
	"io"
	"sync"

	tea "github.com/charmbracelet/bubbletea"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// TUISink is a Sink that renders a Bubble Tea dashboard. The orchestrator
// calls AgentEvent/RunFinished from a single goroutine (CU4 serial-dispatch
// contract); the sink translates each event into a tea.Msg and sends it via
// Program.Send. Bubble Tea's Send is thread-safe, but we never rely on that
// property — the serial-dispatch promise means Send is only called from the
// orchestrator's dispatch goroutine.
//
// Cancellation: cancel is the same context.CancelFunc that controls the
// orchestrator's run context. KeyCtrlC in the dashboard calls this function
// (gated by a sync.Once in the model). Out-of-TUI SIGINT routes through the
// cobra root's context, which cancels the same function — no parallel
// signal.Notify goroutine is needed here.
type TUISink struct {
	program *tea.Program

	mu       sync.Mutex
	started  bool
	finished bool

	done chan struct{} // closed when the tea.Program exits
}

// Compile-time interface check.
var _ reviewtypes.Sink = (*TUISink)(nil)

// NewTUISink creates a TUISink wired to cancel for Ctrl+C handling. agents is
// the ordered list of agent names that will run; the dashboard pre-renders one
// row per agent so the user sees the full run shape from the first frame.
// output is the writer the Bubble Tea program renders into (typically
// cmd.OutOrStdout()).
//
// tea.WithoutSignalHandler keeps SIGINT routing on the cobra root's existing
// handler (which cancels the run context), so the TUI's KeyCtrlC path and the
// OS signal path share a single cancel function with no race.
func NewTUISink(agents []string, cancel context.CancelFunc, output io.Writer) *TUISink {
	model := newReviewTUIModel(agents, cancel)
	prog := tea.NewProgram(
		model,
		tea.WithOutput(output),
		tea.WithoutSignalHandler(), // SIGINT handled by cobra root; KeyCtrlC calls cancel directly
	)
	return &TUISink{
		program: prog,
		done:    make(chan struct{}),
	}
}

// Start spawns the Bubble Tea program in its own goroutine. Must be called
// before any AgentEvent calls. Subsequent calls are no-ops.
func (s *TUISink) Start() {
	s.mu.Lock()
	if s.started {
		s.mu.Unlock()
		return
	}
	s.started = true
	s.mu.Unlock()

	go func() {
		defer close(s.done)
		if _, err := s.program.Run(); err != nil {
			// Bubble Tea program errors are non-actionable in a background
			// goroutine (e.g., terminal resize race on exit). Log nothing —
			// the run result is available via RunSummary and the sink's
			// finished state. Swallowing is intentional.
			_ = err
		}
	}()
}

// Wait blocks until the Bubble Tea program exits. Safe to call after Start.
// If Start was never called, Wait returns immediately.
func (s *TUISink) Wait() {
	s.mu.Lock()
	started := s.started
	s.mu.Unlock()
	if !started {
		return
	}
	<-s.done
}

// AgentEvent (Sink interface): translate ev into a tea.Msg and Send it to the
// Bubble Tea program. Implements the serial-dispatch contract: the orchestrator
// calls this from a single goroutine.
//
// Note: Send is safe to call from goroutines other than the TUI's update loop;
// Bubble Tea's implementation queues the message internally.
func (s *TUISink) AgentEvent(agent string, ev reviewtypes.Event) {
	s.mu.Lock()
	ok := s.started && !s.finished
	s.mu.Unlock()
	if !ok {
		return
	}
	s.program.Send(agentEventMsg{agent: agent, ev: ev})
}

// RunFinished (Sink interface): mark the run complete and send the final
// summary message. The TUI shows the dashboard one more frame with the
// terminal statuses and waits for the user to press any key to dismiss.
//
// IMPORTANT: RunFinished blocks until the user dismisses (presses any key)
// so that post-run sinks (e.g. DumpSink) render their narrative AFTER the
// TUI has exited and the terminal is back in normal mode.
func (s *TUISink) RunFinished(summary reviewtypes.RunSummary) {
	s.mu.Lock()
	if s.finished {
		s.mu.Unlock()
		return
	}
	s.finished = true
	s.mu.Unlock()

	s.program.Send(runFinishedMsg{summary: summary})
	// Block until the Bubble Tea program exits (user presses any key after
	// seeing the final dashboard, or Ctrl+C was already received and the
	// program already quit).
	s.Wait()
}

				PerRunPrompt: picked.PerRun,
				ScopeBaseRef: scopeBaseRef,
				StartingSHA:  headSHA,
			},
		})
	}

	// Compose sinks based on TTY detection.
	// TTY mode: [TUISink, DumpSink] — TUI owns the live dashboard; DumpSink
	// renders the post-run narrative after TUI dismisses (RunFinished is called
	// on each sink in order, and TUISink.RunFinished blocks until user dismisses).
	// Non-TTY mode: [DumpSink] alone.
	//
	// A derived context is used so the TUI's Ctrl+C handler can cancel the run
	// via the same cancelRun function that the orchestrator's context is built on.
	runCtx, cancelRun := context.WithCancel(ctx)
	defer cancelRun()

	agentNames := make([]string, len(reviewers))
	for i, r := range reviewers {
		agentNames[i] = r.Name()
	}

	// TUI requires both:
	//   - terminal stdout (otherwise ANSI codes corrupt redirected output)
	//   - a promptable stdin (otherwise the post-run dismissal loop blocks
	//     forever — happens when entire review is invoked from inside an
	//     agent like Claude Code or Gemini CLI, where stdout is a TTY but
	//     keypresses are never delivered)
	var sinks []reviewtypes.Sink
	if interactive.IsTerminalWriter(out) && interactive.CanPromptInteractively() {
		tuiSink := NewTUISink(agentNames, cancelRun, out)
		tuiSink.Start()
		defer tuiSink.Wait()
		sinks = append(sinks, tuiSink)
		sinks = append(sinks, DumpSink{W: out})
	} else {
		sinks = append(sinks, DumpSink{W: out})
	}

	_, waitErr := RunMulti(runCtx, reviewers, reviewtypes.RunConfig{}, sinks)
	if waitErr != nil && runCtx.Err() == nil && ctx.Err() == nil {
		return fmt.Errorf("review run: %w", waitErr)
	}
	return nil
}

// handlePickerError maps multi-picker error sentinels to the appropriate
// command-layer response.
//   - ErrPickerCancelled → return nil (user cancelled; no error shown)
//   - ErrNoAgentsSelected → surface error to user
//   - other errors → surface to user
func handlePickerError(cmd *cobra.Command, silentErr func(error) error, pickErr error) error {
	if errors.Is(pickErr, ErrPickerCancelled) {
		return nil
	}
	cmd.SilenceUsage = true
	fmt.Fprintln(cmd.ErrOrStderr(), pickErr.Error())
	return silentErr(pickErr)
}

// Package review — see env.go for package-level rationale.
//
// synthesis_sink.go provides SynthesisSink, an opt-in Sink that prompts the
// user (y/N, default N) after all agents finish, then asks a configured
// summary provider to synthesize a unified verdict across the per-agent
// narratives. Skipped silently in non-TTY mode, on cancellation, or when
// fewer than 2 agents produced usable output.
//
// Composition: appended AFTER DumpSink in TTY-mode sink slices, so the
// y/N prompt appears below the per-agent narrative dump.
package review

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"

	"github.com/charmbracelet/huh"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// SynthesisProvider abstracts the LLM call that produces the cross-agent
// verdict. Injected via Deps so tests can stub the provider call without a
// real API roundtrip. Production wiring (in review_bridge.go) calls into
// the same provider entire explain uses.
type SynthesisProvider interface {
	// Synthesize takes the composed synthesis prompt and returns the
	// verdict text. Errors are surfaced to the caller; SynthesisSink
	// degrades gracefully on error rather than failing the run.
	Synthesize(ctx context.Context, prompt string) (string, error)
}

// SynthesisSink composes a multi-agent verdict by calling a configured
// summary provider after the run finishes. AgentEvent is a no-op; all
// work happens in RunFinished.
type SynthesisSink struct {
	Provider     SynthesisProvider
	Writer       io.Writer
	InputTTY     bool // true if stdin can prompt the user
	PromptYN     func(ctx context.Context, question string, def bool) (bool, error)
	PerRunPrompt string // if non-empty, included in the synthesis prompt for context
}

// Compile-time interface check.
var _ reviewtypes.Sink = SynthesisSink{}

// AgentEvent is a no-op; SynthesisSink only acts in RunFinished.
func (SynthesisSink) AgentEvent(_ string, _ reviewtypes.Event) {}

// RunFinished optionally synthesizes a cross-agent verdict.
//
// Skip silently when:
//   - stdin isn't a TTY (s.InputTTY == false)
//   - the run was cancelled (summary.Cancelled)
//   - fewer than 2 agents produced usable output (status Succeeded or Failed
//     with non-empty narrative buffer)
//
// Otherwise prompt y/N (default N). On y: compose prompt, call provider,
// print response. On provider failure: print "synthesis unavailable: <err>"
// with the underlying error; user can still commit.
func (s SynthesisSink) RunFinished(summary reviewtypes.RunSummary) {
	if !s.InputTTY {
		return
	}
	if summary.Cancelled {
		return
	}
	if usableAgentCount(summary) < 2 {
		return
	}

	ctx := context.Background()
	promptFn := s.PromptYN
	if promptFn == nil {
		promptFn = realPromptYN
	}

	yes, err := promptFn(ctx, "Synthesize a unified verdict across all agent reviews?", false)
	if err != nil {
		// huh form errors (terminal-resize anomalies, stdin EOF, stub
		// failures) shouldn't block the user from committing — they get the
		// same silent skip as a "no" answer. Logged at debug for diagnostics.
		logging.Debug(ctx, "synthesis prompt error",
			slog.String("error", err.Error()))
		return
	}
	if !yes {
		return
	}

	synthesisPrompt := composeSynthesisPrompt(summary, s.PerRunPrompt)
	result, provErr := s.Provider.Synthesize(ctx, synthesisPrompt)
	if provErr != nil {
		fmt.Fprintf(s.Writer, "synthesis unavailable: %v\n", provErr)
		return
	}
	fmt.Fprintln(s.Writer, result)
}

// usableAgentCount returns the number of agents that produced usable narrative
// output (non-empty AssistantText in their buffer). Used to determine whether
// synthesis is worth offering.
func usableAgentCount(summary reviewtypes.RunSummary) int {
	return len(usableAgentRuns(summary))
}

// realPromptYN is the production y/N prompt using a huh Confirm form.
// Default is false (N). On user cancellation (Ctrl+C) returns false, nil so
// the caller treats it as a "no" answer; on real form errors the error is
// returned so RunFinished can log it via the debug-error path.
func realPromptYN(ctx context.Context, question string, def bool) (bool, error) {
	answer := def
	form := newAccessibleForm(huh.NewGroup(
		huh.NewConfirm().
			Title(question).
			Value(&answer),
	))
	if err := form.RunWithContext(ctx); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
			return false, nil
		}
		return false, fmt.Errorf("synthesis confirm form: %w", err)
	}
	return answer, nil
}

package cli

// review_bridge.go wires cli-package implementations into the review
// subpackage's NewCommand Deps struct. Functions that need checkpoint
// access (headHasReviewCheckpoint) and per-agent reviewer constructors
// (launchableReviewerFor) live here to avoid the import cycle:
//   review → checkpoint → codex → review
//   review → claudecode/codex/geminicli → review

import (
	"bytes"
	"context"
	"fmt"
	"strings"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/agent/codex"
	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	cliReview "github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// buildReviewDeps builds the review.Deps struct used by review.NewCommand.
// attachCmd is the cobra.Command for `entire review attach`; pass nil in
// tests that don't need the subcommand.
//
// SynthesisProvider is a lazySynthesisProvider that defers resolution of the
// configured summary provider to the first Synthesize call. This avoids
// running resolveCheckpointSummaryProvider during CLI startup (and during
// every `entire review --help` invocation in tests). Note: side effects are
// DEFERRED, not eliminated — see lazySynthesisProvider doc below.
func buildReviewDeps(attachCmd *cobra.Command) cliReview.Deps {
	return cliReview.Deps{
		GetAgentsWithHooksInstalled: GetAgentsWithHooksInstalled,
		NewSilentError: func(err error) error {
			return NewSilentError(err)
		},
		HeadHasReviewCheckpoint: headHasReviewCheckpoint,
		ReviewerFor:             launchableReviewerFor,
		PromptForAgentFn:        nil, // use real PromptForAgent
		AttachCmd:               attachCmd,
		SynthesisProvider:       lazySynthesisProvider{},
	}
}

// lazySynthesisProvider wraps the summary-provider resolution so it runs
// only when Synthesize is first called (not at CLI startup).
//
// IMPORTANT: side effects are DEFERRED, not eliminated. resolveCheckpoint-
// SummaryProvider auto-selects a default provider AND persists the choice
// to .entire/settings.local.json (via persistSummaryProviderSelection) on
// the FIRST call against an unconfigured repo. The disk write still
// happens — it's just triggered by the user picking "y" on the synthesis
// prompt, not by every `entire review --help`.
//
// If a future caller needs read-only resolution (e.g. CI mode, where
// touching settings would dirty the working tree), introduce a flag on
// resolveCheckpointSummaryProvider for skip-persistence.
type lazySynthesisProvider struct{}

// Synthesize resolves the configured summary provider on demand and delegates
// the generation call to the underlying TextGenerator. Errors from resolution
// are returned to SynthesisSink, which prints "synthesis unavailable: <err>"
// and lets the user continue without blocking the commit.
//
// resolveCheckpointSummaryProvider's user-facing chatter (auto-select notice,
// "Using <provider>" line, external_agents flag-flip note, persistence-failure
// warning) is captured and routed through logging instead of printing inline
// with the synthesis output. The persistence-failure path is also surfaced as
// logging.Warn at the source (explain_summary_provider.go), so real failures
// are not silenced — they live in .entire/logs/.
//
// Note: first call against an unconfigured repo will write
// .entire/settings.local.json — see the lazySynthesisProvider doc above.
func (lazySynthesisProvider) Synthesize(ctx context.Context, prompt string) (string, error) {
	var captured bytes.Buffer

	var captured bytes.Buffer
	provider, err := resolveCheckpointSummaryProvider(ctx, &captured)
	logProviderResolutionOutput(ctx, &captured)
	if err != nil {
		return "", err
	}
	ag, agErr := getSummaryAgent(provider.Name)
	if agErr != nil {
		return "", agErr
	}
	tg, ok := agent.AsTextGenerator(ag)
	if !ok {
		return "", fmt.Errorf("agent %s does not support text generation", provider.Name)
	}
	return tg.GenerateText(ctx, prompt, provider.Model) //nolint:wrapcheck // SynthesisSink owns display
}

// logProviderResolutionOutput routes captured output from resolveCheckpoint-
// SummaryProvider through logging so it ends up in .entire/logs/ rather than
// inline with the synthesis verdict. Lines starting with "Warning:" go to
// Warn; other notices (auto-select reason, "Using X for summary generation",
// external_agents flag-flip note) go to Info.
func logProviderResolutionOutput(ctx context.Context, buf *bytes.Buffer) {
	for _, line := range strings.Split(strings.TrimRight(buf.String(), "\n"), "\n") {
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "Warning:") {
			logging.Warn(ctx, "synthesis provider resolution", "message", line)
			continue
		}
		logging.Info(ctx, "synthesis provider resolution", "message", line)
	}
}

// launchableReviewerFor returns the AgentReviewer for known launchable agents,
// or nil for non-launchable agents (cursor, opencode, factoryai-droid,
// copilot-cli). This lives in the cli package to avoid the import cycle:
//
//	review/cmd.go → claudecode/codex/geminicli → review
func launchableReviewerFor(agentName string) reviewtypes.AgentReviewer {
	switch agentName {
	case string(agent.AgentNameClaudeCode):
		return claudecode.NewReviewer()
	case string(agent.AgentNameCodex):
		return codex.NewReviewer()
	case string(agent.AgentNameGemini):
		return geminicli.NewReviewer()
	default:
		return nil
	}
}

package claudecode

import (
	"context"
	"errors"
	"log/slog"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/mod/semver"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/skilldiscovery"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// DiscoverReviewSkills walks Claude Code's on-disk plugin layout and user-
// level directories looking for review-adjacent invocations. Returns
// (nil, nil) when HOME is unreadable or directories are missing — discovery
// is best-effort.
//
// Claude Code exposes three kinds of invocable content per plugin:
//   - skills:   <plugin>/skills/<name>/SKILL.md   (YAML frontmatter with name + description)
//   - commands: <plugin>/commands/<name>.md       (YAML frontmatter with description; name = filename)
//   - agents:   <plugin>/agents/<name>.md         (YAML frontmatter with description; name = filename)
//
// All three are walked because users invoke them via the same slash-prefix
// syntax (`/plugin:name`) and any of them can be a review tool. The
// pr-review-toolkit plugin, for example, ships its review skills as
// commands/agents (not skills/), and was silently missed by a skills-only
// walker.
//
//nolint:unparam // error return is part of SkillDiscoverer contract; future implementations may report hard failures
func (c *ClaudeCodeAgent) DiscoverReviewSkills(ctx context.Context) ([]agent.DiscoveredSkill, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		logging.Debug(ctx, "claude-code discovery: UserHomeDir failed", slog.String("error", err.Error()))
		return nil, nil
	}

	var found []agent.DiscoveredSkill
	found = append(found, scanPluginCache(ctx, filepath.Join(home, ".claude", "plugins", "cache"))...)
	found = append(found, scanUserSkills(ctx, filepath.Join(home, ".claude", "skills"))...)
	found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(home, ".claude", "commands"), "")...)
	found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(home, ".claude", "agents"), "")...)
	if len(found) == 0 {
		return nil, nil
	}
	return found, nil
}

// scanPluginCache walks <root>/<marketplace>/<plugin>/<version>/{skills,commands,agents}/
// One plugin can contribute through any or all three directories.
//
// Multiple version directories per plugin are common after upgrades. Walking
// every version produces duplicate skills (same invocation name, same
// description) — confusing in the picker and wasteful in the prompt. We pick
// a single version per plugin via pickLatestVersion: prefer valid semver
// (highest), fall back to lexicographic max.
func scanPluginCache(ctx context.Context, root string) []agent.DiscoveredSkill {
	entries, err := os.ReadDir(root)
	if err != nil {
		logging.Debug(ctx, "claude-code discovery: plugin cache unreadable",
			slog.String("root", root), slog.String("error", err.Error()))
		return nil
	}
	var found []agent.DiscoveredSkill
	for _, marketEntry := range entries {
		if !marketEntry.IsDir() {
			continue
		}
		marketRoot := filepath.Join(root, marketEntry.Name())
		pluginEntries, err := os.ReadDir(marketRoot)
		if err != nil {
			continue
		}
		for _, pluginEntry := range pluginEntries {
			if !pluginEntry.IsDir() {
				continue
			}
			pluginName := pluginEntry.Name()
			pluginRoot := filepath.Join(marketRoot, pluginName)
			versionEntries, err := os.ReadDir(pluginRoot)
			if err != nil {
				continue
			}
			versionDir, ok := pickLatestVersion(versionEntries)
			if !ok {
				continue
			}
			versionRoot := filepath.Join(pluginRoot, versionDir)
			found = append(found, readSkillsDir(ctx, filepath.Join(versionRoot, "skills"), pluginName)...)
			found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(versionRoot, "commands"), pluginName)...)
			found = append(found, scanFlatMarkdownDir(ctx, filepath.Join(versionRoot, "agents"), pluginName)...)
		}
	}
	return found
}

// pickLatestVersion returns the name of the "newest" version directory among
// entries. Strategy:
//
//   - If any entry name parses as semver (with or without a leading "v"), pick
//     the highest semver among those that parse. Non-semver entries are
//     ignored when at least one semver entry exists.
//   - Otherwise, fall back to the lexicographic max of all directory names.
//     This handles the "unknown" sentinel some plugins ship and one-off names.
//
// Returns ("", false) if no usable directory entry exists.
func pickLatestVersion(entries []os.DirEntry) (string, bool) {
	var dirs []string
	for _, e := range entries {
		if e.IsDir() {
			dirs = append(dirs, e.Name())
		}
	}
	if len(dirs) == 0 {
		return "", false

		return "", false
	}
	var semverDirs []string
	for _, d := range dirs {
		if semver.IsValid(semverWithV(d)) {
			semverDirs = append(semverDirs, d)
		}
	}
	if len(semverDirs) > 0 {
		sort.Slice(semverDirs, func(i, j int) bool {
			return semver.Compare(semverWithV(semverDirs[i]), semverWithV(semverDirs[j])) > 0
		})
		return semverDirs[0], true
	}
	sort.Sort(sort.Reverse(sort.StringSlice(dirs)))
	return dirs[0], true
}

// semverWithV ensures a version string has the "v" prefix that
// golang.org/x/mod/semver requires. Plugin version dirs are usually bare
// (e.g. "0.1.0"), but we tolerate either form.
func semverWithV(s string) string {
	if strings.HasPrefix(s, "v") {
		return s
	}
	return "v" + s
}

// scanUserSkills walks ~/.claude/skills/<skill>/SKILL.md.
func scanUserSkills(ctx context.Context, root string) []agent.DiscoveredSkill {
	return readSkillsDir(ctx, root, "" /* no plugin prefix */)
}

// readSkillsDir reads each skill subdirectory's SKILL.md, parses frontmatter,
// and emits a DiscoveredSkill if Matches() returns true.
func readSkillsDir(ctx context.Context, dir, pluginName string) []agent.DiscoveredSkill {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var found []agent.DiscoveredSkill
	for _, skillEntry := range entries {
		if !skillEntry.IsDir() {
			continue
		}
		skillDir := filepath.Join(dir, skillEntry.Name())
		skillFile := filepath.Join(skillDir, "SKILL.md")
		data, err := os.ReadFile(skillFile) //nolint:gosec // G304: skillFile is constructed from a ReadDir walk under HOME, not user input
		if err != nil {
			continue
		}
		name, description, parseErr := parseSkillFrontmatter(data)
		if parseErr != nil {
			logging.Debug(ctx, "claude-code discovery: skipping malformed SKILL.md",
				slog.String("path", skillFile), slog.String("error", parseErr.Error()))
			continue
		}
		if name == "" {
			name = skillEntry.Name()
		}
		invocation := invocationName(name, pluginName)

// Package review — see env.go for package-level rationale.
//
// synthesis_prompt.go builds the LLM prompt that asks a configured summary
// provider to synthesize a unified verdict across N per-agent review reports.
// It is a pure-function composer with no I/O; all logic is testable without
// network calls or TTY state.
package review

import (
	"fmt"
	"strings"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// composeSynthesisPrompt builds the LLM prompt asking the provider to
// synthesize a unified verdict across N agent reviews. Format:
//
//	You reviewed the same code change with N agents. Here are their reports:
//
//	─── claude-code ───
//	<narrative from agent's AssistantText events, joined>
//
//	─── codex ───
//	<narrative>
//
//	...
//
//	Synthesize a unified verdict with these sections:
//	  - Common findings (issues all agents flagged)
//	  - Unique findings (issues only one agent caught)
//	  - Disagreements (areas where agents reached different conclusions)
//	  - Priority order (top 5 issues to address first)
//
//	Be concise; aim for ~300 words.
//
//	<perRunPrompt, if any — appended as user's per-run instructions>
//
// Agents with no usable narrative (empty AssistantText) are filtered out
// upstream by usableAgentRuns, so the header count and the body are both
// scoped to agents that produced narrative output. SynthesisSink already
// guards on len(usable) >= 2 before calling, so the empty case won't reach
// the LLM in production.
func composeSynthesisPrompt(summary reviewtypes.RunSummary, perRunPrompt string) string {
	usable := usableAgentRuns(summary)
	if len(usable) == 0 {
		return ""
	}

	var b strings.Builder

	fmt.Fprintf(&b, "You reviewed the same code change with %d agents. Here are their reports:\n", len(usable))

	for _, run := range usable {
		narrative := joinAssistantText(run.Buffer)
		if narrative == "" {
			continue
		}
		fmt.Fprintf(&b, "\n─── %s ───\n", run.Name)
		b.WriteString(narrative)
		b.WriteString("\n")
	}

	b.WriteString(`
Synthesize a unified verdict with these sections:
  - Common findings (issues all agents flagged)
  - Unique findings (issues only one agent caught)
  - Disagreements (areas where agents reached different conclusions)
  - Priority order (top 5 issues to address first)

Be concise; aim for ~300 words.`)

	if perRunPrompt != "" {
		b.WriteString("\n\n")
		b.WriteString(perRunPrompt)
	}

	return b.String()
}

// usableAgentRuns returns agent runs that have non-empty AssistantText
// narrative in their event buffer, in the original order from the summary.
// The filter is on narrative content alone — Status is not checked. In
// practice this drops most cancelled and errored runs (they typically don't
// produce assistant output before exiting), but a cancelled agent that
// emitted text mid-stream is still considered usable. The synthesis prompt
// uses what the agent actually said, regardless of how the run terminated.
func usableAgentRuns(summary reviewtypes.RunSummary) []reviewtypes.AgentRun {
	var result []reviewtypes.AgentRun
	for _, run := range summary.AgentRuns {
		if joinAssistantText(run.Buffer) == "" {
			continue
		}
		result = append(result, run)
	}
	return result
}

// Package mdrender renders markdown to terminal-styled output using the
// shared entire CLI palette (orange H1, cyan H2, indigo H3, plus chroma
// syntax highlighting). Used by `entire dispatch`, `entire review`, and
// any other command that prints LLM-generated markdown to the terminal.
//
// Two entry points:
//   - Render: pure function — caller supplies width and background hint.
//   - RenderForWriter: TTY-aware — renders to a terminal writer with
//     auto-detected width; passes raw markdown through when w is not a
//     terminal (so redirected output is grep-friendly, not full of ANSI).
package mdrender

import (
	"fmt"
	"io"
	"os"

	"github.com/charmbracelet/glamour"
	"github.com/charmbracelet/glamour/ansi"
	glamourstyles "github.com/charmbracelet/glamour/styles"
	"github.com/muesli/termenv"
	"golang.org/x/term"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
)

// DefaultTerminalWidth caps glamour word-wrap when no real terminal width
// is available. Matches the cap used by status_style.getTerminalWidth.
const DefaultTerminalWidth = 80

// Render produces a glamour-styled string from markdown using the entire
// CLI palette. width is the word-wrap target; darkBackground selects the
// dark or light palette variant.
//
// Errors only on glamour renderer construction or render failure — both
// of which indicate a malformed StyleConfig (programmer error) rather
// than a runtime condition.
func Render(markdown string, width int, darkBackground bool) (string, error) {
	renderer, err := glamour.NewTermRenderer(
		glamour.WithStyles(stylesForBackground(darkBackground)),
		glamour.WithWordWrap(width),
		glamour.WithPreservedNewLines(),
	)
	if err != nil {
		return "", fmt.Errorf("initialize markdown renderer: %w", err)
	}
	rendered, err := renderer.Render(markdown)
	if err != nil {
		return "", fmt.Errorf("render markdown: %w", err)
	}
	return rendered, nil
}

// RenderForWriter renders markdown when w is a terminal writer, and returns
// the input unchanged otherwise. NO_COLOR=1 also disables rendering so
// pipelines that grep through redirected output work without unwrapping
// ANSI escape sequences.
//
// Width is auto-detected from w (capped at 80); background palette is
// detected via termenv.HasDarkBackground.
func RenderForWriter(w io.Writer, markdown string) (string, error) {
	if !shouldRender(w) {
		return markdown, nil
	}
	return Render(markdown, terminalWidth(w), termenv.HasDarkBackground())
}

// shouldRender returns true if w is a terminal writer and NO_COLOR is unset.
func shouldRender(w io.Writer) bool {
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	return interactive.IsTerminalWriter(w)
}

// terminalWidth returns the writer's terminal width capped at 80.
// Falls back to stdout/stderr probing, then DefaultTerminalWidth.
func terminalWidth(w io.Writer) int {
	if f, ok := w.(*os.File); ok {
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, DefaultTerminalWidth)
		}
	}
	for _, f := range []*os.File{os.Stdout, os.Stderr} {
		if f == nil {
			continue
		}
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, DefaultTerminalWidth)
		}
	}
	return DefaultTerminalWidth
}

// stylesForBackground returns the entire CLI's glamour StyleConfig.
//
// Palette:
//   - H1: orange (#fb923c) — agent name, top-level section
//   - H2: cyan (#22d3ee) — secondary headings, links
//   - H3: indigo (#818cf8) — tertiary headings, enumerations, keywords

// Package review — see env.go for package-level rationale.
//
// multipicker.go provides spawn-time agent multi-selection and per-run
// prompt collection for multi-agent review runs. When 2+ launchable agents
// are configured AND the user has not passed --agent, the dispatch logic
// in cmd.go calls PickAgents to let the user choose a subset and optionally
// add a one-off prompt without editing settings.
package review

import (
	"context"
	"errors"
	"fmt"
	"sort"

	"github.com/charmbracelet/huh"
)

// PickedAgents is the result of PickAgents: the agents the user selected
// for this run, plus an optional per-run prompt to append to the composed
// review prompt for each agent.
type PickedAgents struct {
	// Names contains the agent registry keys selected by the user,
	// e.g. ["claude-code", "codex"]. Sorted alphabetically.
	Names []string

	// PerRun is optional textarea content; "" when the user skipped or cleared it.
	PerRun string
}

// ErrPickerCancelled is returned when the user aborts the multi-select.
var ErrPickerCancelled = errors.New("agent picker cancelled")

// ErrNoAgentsSelected is returned when the user unchecks all agents.
// Caller should surface a clear error rather than running with zero agents.
var ErrNoAgentsSelected = errors.New("no agents selected for review")

// PickAgents shows a multi-select form populated from eligible (the agents
// that are both configured AND have an AgentReviewer), pre-checks all of
// them, and returns the user's selection plus an optional per-run prompt.
//
// Returns ErrPickerCancelled if the user aborts. An empty selection (user
// unchecked all boxes) returns ErrNoAgentsSelected.
//
// Requires len(eligible) >= 2; returns an error if the caller passes fewer
// than 2 choices — this function is for multi-agent flows only.
func PickAgents(ctx context.Context, eligible []AgentChoice) (PickedAgents, error) {
	if len(eligible) < 2 {
		return PickedAgents{}, fmt.Errorf("PickAgents requires at least 2 eligible agents, got %d", len(eligible))
	}

	// Sort alphabetically for stable display order regardless of how the
	// caller populated the slice.
	sorted := make([]AgentChoice, len(eligible))
	copy(sorted, eligible)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })

	// Build options pre-selected (all agents checked by default — mirrors
	// PR #1018 behaviour so the user can just press Enter to run all).
	options := make([]huh.Option[string], 0, len(sorted))
	for _, c := range sorted {
		options = append(options, huh.NewOption(c.Label, c.Name).Selected(true))
	}

	var picked []string
	multiForm := newAccessibleForm(huh.NewGroup(
		huh.NewMultiSelect[string]().
			Title("Which agents should run this review?").
			Options(options...).
			Value(&picked),
	))
	if err := multiForm.RunWithContext(ctx); err != nil {
		return PickedAgents{}, ErrPickerCancelled
	}

	if len(picked) == 0 {
		return PickedAgents{}, ErrNoAgentsSelected
	}

	// Sort the selection alphabetically so the caller receives a stable slice.
	sort.Strings(picked)

	// Per-run prompt: optional textarea presented after agent selection.
	var perRun string
	promptForm := newAccessibleForm(huh.NewGroup(
		huh.NewText().
			Title("Optional per-run prompt").
			Description("e.g. 'focus on auth' — appended to the review prompt for this run only. Leave blank to skip.").
			Value(&perRun),
	))
	if err := promptForm.RunWithContext(ctx); err != nil {
		// Cancellation on the prompt step (Ctrl+C) propagates as picker
		// cancelled — we don't want an empty prompt here; user can retry.
		return PickedAgents{}, ErrPickerCancelled
	}

	return PickedAgents{Names: picked, PerRun: perRun}, nil
}

